<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,defineAsyncComponent,onErrorCaptured} from 'vue';
import {useRouter} from 'vitepress';
import {readStore} from './storage';
import {library} from './library';
import {getLearning,putLearning} from './learning-store';
import type {ReadingLocator,BookManifest} from './types';
const Scene=defineAsyncComponent(()=>import('./GalaxyScene.vue')),router=useRouter();
const initializing=ref(true);
const phase=ref<'galaxy'|'zoom'|'book'|'opening'>('galaxy'),simple=ref(true),active=ref(true),failed=ref(false),resume=ref(''),reduced=ref(false);let timer:ReturnType<typeof setTimeout>|undefined;let disposed=false;
const book=library.books[0];
function background(){active.value=!document.hidden;}
function choose(){if(phase.value!=='galaxy')return;phase.value=reduced.value?'book':'zoom';if(phase.value==='zoom')timer=setTimeout(()=>phase.value='book',1200);}
async function readBook(){
 const navigate=async()=>{await router.go('/read/title');const end=Date.now()+4000;while(Date.now()<end&&!document.querySelector('.book-holder:not(.loading)'))await new Promise(r=>setTimeout(r,40));};
 if(!reduced.value&&document.startViewTransition)document.startViewTransition(navigate);else await navigate();
}
function enter(){if(phase.value!=='book')return;phase.value='opening';timer=setTimeout(()=>void readBook(),reduced.value?0:800);}
function skip(){clearTimeout(timer);if(phase.value==='opening')void readBook();else phase.value='book';}
function back(){clearTimeout(timer);phase.value='galaxy';}
function simplify(){simple.value=!simple.value;void putLearning('galaxy:simple',simple.value);}
onErrorCaptured(()=>{failed.value=true;return false;});
onMounted(async()=>{reduced.value=matchMedia('(prefers-reduced-motion: reduce)').matches;simple.value=await getLearning('galaxy:simple',reduced.value);try{const canvas=document.createElement('canvas');const gl=canvas.getContext('webgl2');if(!gl)failed.value=true;else gl.getExtension('WEBGL_lose_context')?.loseContext();}catch{failed.value=true;}const place=await getLearning<ReadingLocator|null>('reading',readStore<ReadingLocator|null>('reading',null));if(place){try{const manifest:BookManifest=await fetch('/book/manifest.json').then(r=>r.json());const section=manifest.pages.find(p=>p.id===place.sectionId);if(section)resume.value=section.route+'#'+place.blockId+'@'+place.offset;}catch{}}if(disposed)return;initializing.value=false;document.addEventListener('visibilitychange',background);});
onBeforeUnmount(()=>{disposed=true;clearTimeout(timer);document.removeEventListener('visibilitychange',background);});
</script>
<template><main class="galaxy-library" :data-phase="phase">
 <Scene v-if="!simple&&!failed" :zoom="phase!=='galaxy'" :active="active&&!reduced" @failed="failed=true"/>
 <div v-else class="galaxy-static" aria-hidden="true"/>
 <header class="galaxy-header"><a href="/">PLEX <span>星轨书库</span></a><button :aria-pressed="simple" :disabled="initializing" @click="simplify">{{simple?'开启三维':'简化模式'}}</button></header>
 <div v-if="phase==='galaxy'||phase==='zoom'" class="galaxy-intro"><h1>每一本书，<br>都是一个新世界。</h1><p>选择一颗星球，进入它的知识太阳系。</p></div>
 <nav v-if="phase==='galaxy'||phase==='zoom'" class="planet-orbits" aria-label="书籍星球"><button v-for="(entry,i) in library.books" :key="entry.id" :class="['library-planet','planet-'+i]" :disabled="entry.status==='coming'||phase==='zoom'" :style="{'--planet-color':entry.color}" @click="choose"><span class="planet-sphere"/><strong>{{entry.title}}</strong><small>{{entry.subtitle}}</small><span>{{entry.status==='available'?'进入这颗星球':'待上架'}}</span></button></nav>
 <section v-else class="physical-book-stage" aria-label="中央实体书"><div class="book-contact-shadow"/><button class="physical-book" aria-label="翻开星轨编程" :disabled="phase==='opening'" @click="enter"><span class="physical-paper">星轨编程<br><small>Python 与算法的探索之旅</small></span><img class="physical-front" :src="book.cover" alt="PLEX 星轨编程封面"/><span class="physical-spine">PLEX · 星轨编程</span></button><p>{{phase==='opening'?'正在翻开书页…':'点击封面，开始阅读'}}</p></section>
 <footer class="galaxy-footer"><button v-if="phase!=='galaxy'" @click="back">返回银河</button><button v-if="phase==='zoom'||phase==='opening'" @click="skip">跳过动画</button><a v-if="resume" :href="resume">继续阅读</a><span v-if="failed" role="status">当前使用静态星球，可正常阅读</span><small>书库 / 1 本已上架 · 2 个新书席位</small></footer>
</main></template>
<style>
.galaxy-library{position:relative;min-height:100dvh;overflow:hidden;background:#060c18;color:#ebf4ff;font-family:'Noto Sans SC',sans-serif}.galaxy-canvas,.galaxy-static{position:absolute;inset:0}.galaxy-static{background:radial-gradient(ellipse at 58% 52%,#35687955,transparent 48%),radial-gradient(ellipse at 35% 70%,#55476b40,transparent 55%),#060c18}.galaxy-static:after{content:'';position:absolute;inset:0;background-image:radial-gradient(#bee5ec 1px,transparent 1px),radial-gradient(#adb9d7 1px,transparent 1px);background-size:79px 89px,137px 157px;background-position:24px 38px;opacity:.4}.galaxy-header,.galaxy-footer{position:relative;z-index:2;display:flex;align-items:center;gap:24px;padding:28px 5vw}.galaxy-header{justify-content:space-between}.galaxy-header a{font-size:26px;font-weight:700;color:inherit;text-decoration:none}.galaxy-header span{font-size:15px;font-weight:400;margin-left:18px}.galaxy-library button,.galaxy-library a{touch-action:manipulation}.galaxy-header button,.galaxy-footer button,.galaxy-footer a{border:1px solid #7896ae;border-radius:4px;background:#102238b8;color:#ecf7ff;padding:11px 18px;font:inherit;text-decoration:none;cursor:pointer}.galaxy-intro{position:relative;z-index:1;padding:3vh 7vw;pointer-events:none}.galaxy-intro h1{font:500 clamp(28px,4vw,54px)/1.4 'Noto Serif SC',serif;margin:0 0 18px}.galaxy-intro p{color:#bfd1df}.planet-orbits{position:relative;z-index:1;min-height:42vh;display:flex;align-items:center;justify-content:center;gap:8vw;padding:24px}.library-planet{display:flex;flex-direction:column;align-items:center;gap:12px;color:#ecf7ff;background:none;border:0;cursor:pointer;max-width:30vw;text-align:center;font:inherit}.planet-sphere{display:block;width:clamp(90px,15vw,200px);aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 30% 24%,#e0edf0,var(--planet-color) 20%,#172436 70%,#050a12);box-shadow:0 0 45px color-mix(in srgb,var(--planet-color) 28%,transparent),inset -20px -12px 30px #0009}.planet-0 .planet-sphere{width:clamp(130px,20vw,270px)}.library-planet:disabled{cursor:default;color:#b8c9da;opacity:1}.library-planet:disabled .planet-sphere{filter:saturate(.55)}.library-planet small{font-size:12px}.library-planet>span:last-child{font-size:12px;color:#afdbdf}.library-planet:focus-visible{outline:2px solid #e7c784;outline-offset:12px}.galaxy-footer{flex-wrap:wrap;justify-content:center;min-height:90px}.galaxy-footer small{color:#a8b8c8}.galaxy-library[data-phase=zoom] .planet-0{transform:scale(1.35);opacity:0;transition:transform 1.2s,opacity 1.2s}.physical-book-stage{position:relative;min-height:70vh;display:flex;flex-direction:column;justify-content:center;align-items:center;perspective:1400px;padding:30px 0 60px}.physical-book{position:relative;width:min(30vw,310px);min-width:200px;aspect-ratio:2/3;transform-style:preserve-3d;transform:rotateY(-12deg) rotateX(3deg);border:0;padding:0;background:#f7eedb;cursor:pointer;box-shadow:16px 12px 40px #0008;transition:transform .8s}.physical-front{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;transform-origin:left center;transform:translateZ(16px);backface-visibility:hidden;transition:transform .8s cubic-bezier(.2,.7,.2,1)}.physical-paper{position:absolute;inset:4px 0 4px 0;background:repeating-linear-gradient(0deg,#f7eedb 0px,#f7eedb 3px,#d7ccba 4px);color:#34342c;display:flex;justify-content:center;align-items:center;flex-direction:column;gap:24px;font:26px 'Noto Serif SC';transform:translateZ(8px)}.physical-paper small{font-size:12px}.physical-spine{position:absolute;left:-16px;top:0;width:16px;height:100%;background:#17333a;color:#e6d7b7;writing-mode:vertical-rl;font-size:10px;padding-top:30px;transform:rotateY(-90deg);transform-origin:right}.book-contact-shadow{position:absolute;width:320px;height:50px;background:#0008;filter:blur(24px);bottom:30px}.physical-book-stage>p{margin-top:32px;color:#b3ccd6}.galaxy-library[data-phase=opening] .physical-front{transform:translateZ(16px) rotateY(-155deg)}.galaxy-library[data-phase=opening] .physical-book{transform:rotateY(0) scale(1.15)}@media(max-width:600px){.galaxy-header{padding:20px}.galaxy-intro{padding:4vh 7vw}.planet-orbits{gap:18px;flex-wrap:wrap}.library-planet{max-width:42vw}.planet-0{min-width:90vw;order:-1}.planet-sphere{width:90px}.planet-0 .planet-sphere{width:160px}.library-planet strong{font-size:14px}.physical-book{width:55vw}.galaxy-footer{gap:12px;padding:20px}}@media(prefers-reduced-motion:reduce){.galaxy-library *{transition:none!important}}
</style>
